/**
 * The sign-up confirmation email (Supabase Auth's "Confirm signup" template,
 * generated by supabase/email-templates/_source/build.py and pasted in the
 * dashboard) shows the 6-digit code to type into the app, and keeps the
 * confirmation link below it: app versions already installed only know the
 * link. No other email gains a code.
 */
import { describe, expect, it } from 'vitest';
import { EMAIL_TEMPLATES } from '../../../supabase/functions/_shared/email-templates';
import { SIGNUP_CODE_LENGTH } from '../signupCode';

const HTML = import.meta.glob('../../../supabase/email-templates/*.html', {
  query: '?raw',
  import: 'default',
  eager: true,
}) as Record<string, string>;
const BUILD = Object.values(
  import.meta.glob('../../../supabase/email-templates/_source/build.py', { query: '?raw', import: 'default', eager: true }) as Record<string, string>,
)[0];

const template = (name: string): string => {
  const hit = Object.entries(HTML).find(([file]) => file.endsWith(`/${name}.html`));
  if (!hit) throw new Error(`no template ${name}.html`);
  return hit[1];
};
const count = (text: string, needle: string) => text.split(needle).length - 1;

const TOKEN = '{{ .Token }}';
const LINK = '{{ .ConfirmationURL }}';

describe('Confirm signup email', () => {
  const html = template('confirm-signup');

  it('shows the code once, large, in its own box', () => {
    expect(count(html, TOKEN)).toBe(1);
    expect(html).toMatch(/class="bw-code"[^>]*>\{\{ \.Token \}\}<\/div>/);
    expect(html).toContain('Enter this code in BandWith');
  });

  it('keeps the confirmation link below the code, as a button and as a link to paste', () => {
    expect(html).toContain(`href="${LINK}"`);
    expect(count(html, LINK)).toBeGreaterThanOrEqual(3); // button, fallback href, fallback text
    expect(html).toContain('Or use this link');
    expect(html.indexOf(TOKEN)).toBeGreaterThan(-1);
    expect(html.indexOf(TOKEN)).toBeLessThan(html.indexOf(`href="${LINK}"`));
  });

  it('still says who it is for and what to do if it was not them', () => {
    expect(html).toContain('{{ .Email }}');
    expect(html).toContain('Not you?');
  });

  it('the preview shows a code of the app’s length', () => {
    const sample = BUILD.match(/replace\("\{\{ \.Token \}\}", "(\d+)"\)/);
    expect(sample?.[1]).toHaveLength(SIGNUP_CODE_LENGTH);
  });
});

describe('every other email', () => {
  it.each(['reset-password', 'magic-link', 'change-email'])('%s has a link and no code', (name) => {
    const html = template(name);
    expect(html).toContain(LINK);
    expect(html).not.toContain(TOKEN);
    expect(html).not.toContain('bw-code"');
  });

  it('reauthentication keeps its code and has no link', () => {
    const html = template('reauthentication');
    expect(count(html, TOKEN)).toBe(1);
    expect(html).not.toContain(LINK);
  });

  it('the emails send-email renders (invites, welcome, quotes…) carry no code', () => {
    for (const [name, t] of Object.entries(EMAIL_TEMPLATES)) {
      expect(t.html, name).not.toContain('.Token');
      expect(t.html, name).not.toContain('bw-code"');
    }
  });

  it('only the sign-up confirmation and reauthentication templates use the code', () => {
    const withCode = Object.entries(HTML)
      .filter(([, html]) => html.includes(TOKEN))
      .map(([file]) => file.split('/').pop())
      .sort();
    expect(withCode).toEqual(['confirm-signup.html', 'reauthentication.html']);
  });
});
